    "browser": {
      "timeout_ms": 45000,
      "wait_for_selector": "article, .post, .item",
      "screenshot_on_error": true
    }
  },

  "quality_thresholds": {
    "min_score_to_include": 3,
    "target_items": 20,
    "early_stop_threshold": 25
  }
}
